// Client-side search and filtering for initiatives.html: free text, country,
// type and a start-year range. No dependencies, ES5 only, safe to open
// straight from the file system. The list is plain HTML generated by
// tools/build-site.js; each <li> carries data-country, data-type and
// data-year, and without JavaScript the whole list simply reads.
(function (root) {
  'use strict';

  function normalise(text) {
    return String(text || '').toLowerCase().replace(/\s+/g, ' ').replace(/^ | $/g, '');
  }

  // A whole number from a form value, or null when blank or not a year.
  function toYear(value) {
    var v = String(value == null ? '' : value).replace(/^\s+|\s+$/g, '');
    if (!/^\d{1,4}$/.test(v)) return null;
    return parseInt(v, 10);
  }

  // item: { text, country, type, year }; criteria: { q, country, type, from, to }.
  // Every query term must appear in the text, so "liberia women" narrows.
  function matches(item, criteria) {
    var terms = normalise(criteria.q) === '' ? [] : normalise(criteria.q).split(' ');
    var text = normalise(item.text);
    for (var i = 0; i < terms.length; i++) {
      if (text.indexOf(terms[i]) === -1) return false;
    }
    if (criteria.country && item.country !== criteria.country) return false;
    if (criteria.type && item.type !== criteria.type) return false;
    var from = toYear(criteria.from);
    var to = toYear(criteria.to);
    if (from !== null && item.year < from) return false;
    if (to !== null && item.year > to) return false;
    return true;
  }

  // Read criteria from a query string such as "?q=women&country=LR&from=2000".
  function parseQuery(search) {
    var out = { q: '', country: '', type: '', from: '', to: '' };
    var pairs = String(search || '').replace(/^\?/, '').split('&');
    for (var i = 0; i < pairs.length; i++) {
      if (!pairs[i]) continue;
      var eq = pairs[i].indexOf('=');
      var key = eq === -1 ? pairs[i] : pairs[i].slice(0, eq);
      var raw = eq === -1 ? '' : pairs[i].slice(eq + 1);
      var value;
      try {
        value = decodeURIComponent(raw.replace(/\+/g, ' '));
      } catch (err) {
        value = raw;
      }
      if (out.hasOwnProperty(key)) out[key] = value;
    }
    return out;
  }

  function toQuery(criteria) {
    var keys = ['q', 'country', 'type', 'from', 'to'];
    var parts = [];
    for (var i = 0; i < keys.length; i++) {
      var v = String(criteria[keys[i]] || '').replace(/^\s+|\s+$/g, '');
      if (v) parts.push(keys[i] + '=' + encodeURIComponent(v));
    }
    return parts.length ? '?' + parts.join('&') : '';
  }

  root.WorldPeaceInitiatives = { matches: matches, parseQuery: parseQuery, toQuery: toQuery };

  if (!root.document || !root.document.addEventListener) return;
  var document = root.document;

  document.addEventListener('DOMContentLoaded', function () {
    var form = document.getElementById('initiative-filters');
    var list = document.getElementById('initiative-list');
    var status = document.getElementById('initiative-status');
    if (!form || !list) return;

    var fields = {
      q: document.getElementById('initiative-search'),
      country: document.getElementById('initiative-country'),
      type: document.getElementById('initiative-type'),
      from: document.getElementById('initiative-from'),
      to: document.getElementById('initiative-to')
    };

    var items = [];
    var lis = list.getElementsByTagName('li');
    var minYear = null;
    var maxYear = null;
    for (var i = 0; i < lis.length; i++) {
      var year = parseInt(lis[i].getAttribute('data-year'), 10);
      items.push({
        el: lis[i],
        text: lis[i].textContent || '',
        country: lis[i].getAttribute('data-country') || '',
        type: lis[i].getAttribute('data-type') || '',
        year: year
      });
      if (!isNaN(year)) {
        if (minYear === null || year < minYear) minYear = year;
        if (maxYear === null || year > maxYear) maxYear = year;
      }
    }
    if (minYear !== null) {
      fields.from.setAttribute('placeholder', String(minYear));
      fields.to.setAttribute('placeholder', String(maxYear));
    }

    function current() {
      var c = {};
      for (var k in fields) {
        if (fields.hasOwnProperty(k) && fields[k]) c[k] = fields[k].value;
      }
      return c;
    }

    function say(message) {
      if (!status) return;
      status.textContent = message;
      if (message) status.removeAttribute('hidden');
      else status.setAttribute('hidden', 'hidden');
    }

    function apply() {
      var criteria = current();
      var shown = 0;
      for (var i = 0; i < items.length; i++) {
        var hit = matches(items[i], criteria);
        items[i].el.style.display = hit ? '' : 'none';
        if (hit) shown++;
      }
      var filtered = toQuery(criteria) !== '';
      if (!filtered) say('');
      else if (shown === 0) say('No initiatives match these filters. Try fewer filters or a wider year range.');
      else say('Showing ' + shown + ' of ' + items.length + ' initiative' + (items.length === 1 ? '' : 's') + '.');
      mirror(criteria);
    }

    // Keep the address bar in step so a filtered list can be linked to. Some
    // file:// loads refuse replaceState; a failure here must not break search.
    function mirror(criteria) {
      if (!root.history || !root.history.replaceState) return;
      try {
        root.history.replaceState(null, '', root.location.pathname + toQuery(criteria) + root.location.hash);
      } catch (err) { /* file:// or a sandboxed frame: harmless */ }
    }

    // Deep link: initiatives.html?country=LR&type=dialogue arrives filtered.
    var initial = parseQuery(root.location.search);
    for (var key in fields) {
      if (fields.hasOwnProperty(key) && fields[key] && initial[key]) fields[key].value = initial[key];
    }

    form.addEventListener('input', apply);
    form.addEventListener('change', apply);
    form.addEventListener('submit', function (e) { e.preventDefault(); apply(); });
    // The reset event fires before the fields clear; apply once they have.
    form.addEventListener('reset', function () { setTimeout(apply, 0); });

    form.removeAttribute('hidden');
    apply();
  });
})(this);
